def add(q,stem,conditions,values,verdicts,reasons,answer,solution,core,knowledge,theories,citations=(),ambiguity='',concept='concept_051'):
 r=by[q];assert len(values)==len(verdicts)==len(reasons)==5
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions=conditions,choices={str(i):dict(value=v,verdict=j,reason=w) for i,(v,j,w) in enumerate(zip(values,verdicts,reasons),1)},figures='図なし。原典頁画像で選択方向、観察条件、鉱物名と全5肢を確認。',ambiguity=ambiguity,evidence=[f'extracted/pages/{r["source_year_directory"]}/17_applied_science/page_{p:03}.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],core_concept=core,required_knowledge=knowledge,solution=solution,independent_answer=str(answer),answer_reason=solution,learning_points='観察モード・切断方位・組成を確認し、'+core+'を他の標本にも適用する。',theory_references=['theory:mineral:'+t for t in theories],discipline_id='geo_mineral',concept_id=concept,classification_reason='全条件・全肢を原典画像で照合。'+core+'を問う鉱物同定・結晶特性の問題である。',calculation='false',figure='false',law='false',evaluation=dict(knowledge_novelty='2',reasoning_steps='1',calculation_load='0',figure_reading='0',difficulty='2',difficulty_reason='偏光の物理は既知でも、造岩鉱物の性質と観察条件は地学固有の知識を要する。'),citations=list(citations),foundationality='high',transferability='high'))
def candidate(q,stem,values,answer,reasons,solution,core,knowledge,theories,citations=(),conditions=None):
 add(q,stem,conditions or {'方向':'条件に最も該当する鉱物を選ぶ。'},values,['条件に一致' if i==answer else '条件に不一致' for i in range(1,6)],reasons,answer,solution,core,knowledge,theories,citations)
for q,values,ans in [('H24-REG-APPLIED-24',['黄鉄鉱','普通角閃石','単斜輝石','黒雲母','ジルコン'],1),('R01-RET-APPLIED-25',['普通角閃石','斜長石','黄鉄鉱','単斜輝石','黒雲母'],3)]:
 reasons={'黄鉄鉱':'不透明な硫化鉱物である。通常の透過薄片では内部の光学性を調べにくく、反射光観察等を要する。','普通角閃石':'通常の薄片では透過光による多色性、劈開、消光などを観察できる。','単斜輝石':'通常の薄片では屈折率、劈開、消光などが同定の手掛かりとなる。','黒雲母':'通常の薄片で強い多色性と一方向の劈開を観察できる。','ジルコン':'小粒でも透明な薄片で高い屈折率・複屈折等を観察できる。','斜長石':'通常の薄片で双晶・消光・累帯構造等を観察できる。'}
 candidate(q,'偏光顕微鏡を用いる同定が最も難しい鉱物を選ぶ。',values,ans,[reasons[v] for v in values],f'通常の岩石薄片を透過光で見る観察を想定すると、不透明な黄鉄鉱が最も不利であるため{ans}を選ぶ。他の候補は透過光学的特徴を利用できる。原典は透過光と明記しておらず、反射偏光顕微鏡なら黄鉄鉱も観察できるので、あらゆる偏光観察で同定不能という意味には拡張しない。','不透明鉱物と透過・反射観察の使い分け','硫化物、岩石薄片、オープン・クロスニコル、反射顕微鏡。',['observation'],['hom_pyrite'],conditions={'方向':'偏光顕微鏡による同定が最も難しいもの。','観察法':'原典に透過光の明記なし。通常の岩石薄片の透過観察として解釈する。'})
add('H25-REG-APPLIED-22','比重2.85以上という重鉱物の定義を使い、重鉱物に分類されないものを選ぶ。',{'境界':'原典は重鉱物を比重2.85以上と定義する。','方向':'重鉱物に分類されないもの。'},['黒雲母','かんらん石','石英','普通輝石','磁鉄鉱'],['組成次第で境界をまたぐ','重鉱物に該当','明確に軽鉱物','重鉱物に該当','重鉱物に該当'],['黒雲母の密度は2.7〜3.3g/cm³と報告され、2.85を下回る組成もある。一律の分類には留保が必要である。','Mg端成分のフォルステライトでも密度約3.275g/cm³であり、境界より高い。','石英の代表密度約2.65g/cm³は境界より低い。','普通輝石の報告密度3.19〜3.56g/cm³は境界より高い。','磁鉄鉱の代表密度約5.175g/cm³は境界より高い。'],3,'石英の代表比重は約2.65で、2.85以上という定義を満たさないので3を独立に選ぶ。ただし黒雲母は組成依存で2.7〜3.3という範囲があり、1も無条件に重鉱物とは断定できない。最も明確な軽鉱物と、問題文が省いた組成条件とを分けて記録する。','密度による重鉱物区分と組成依存性','比重と密度の対応、分離用密度境界、固溶体の物性幅。',['density','composition'],['hom_biotite','hom_quartz','hom_forsterite','hom_augite','hom_magnetite'],ambiguity='原典は黒雲母の組成又は代表密度を指定しない。MSA Handbookの黒雲母密度2.7〜3.3g/cm³は設問境界2.85をまたぐため、1を一律に重鉱物とする根拠が不足する。独立選択は最も明確に境界未満の石英3。選択肢の単一性に関する疑義を残し部分校正とする。')
add('H25-REG-APPLIED-23','造岩鉱物の偏光顕微鏡下の特徴から、最も不適切なものを選ぶ。',{'方向':'最も不適切。','対象':'通常の透過岩石薄片。消光角は適切な結晶切断面で判定する。'},['石英は無色で多色性がない','カリ長石の屈折率は石英より低い','斜長石には累帯構造がしばしば見られる','黒雲母には2方向の明瞭な劈開がある','普通角閃石は直消光しない'],['通常の薄片で正しい','正しい','正しい','誤り','通常の特徴として正しい／切断面依存'],['通常の石英薄片は無色であり、方向に依存する吸収色の変化は目立たない。','正長石の主屈折率約1.518〜1.525は石英の1.544〜1.553より低い。','成長中の組成変化が結晶の内外の光学性に現れる。','黒雲母の卓越する劈開は底面(001)の一方向である。','普通角閃石は通常斜消光を特徴とするが、見掛けの角度は切断方位に依存するので任意の一粒だけで断定しない。'],4,'黒雲母は層状ケイ酸塩で、層に平行な一方向の劈開が明瞭である。二方向という4が誤りとなる。他の肢は通常の薄片観察の特徴に合う。直消光・斜消光の識別では切断方位により見掛け角が変わることを忘れない。','劈開・屈折率・消光を組み合わせる同定','層状構造、オープンでの吸収色、クロスでの消光、組成累帯。',['cleavage','observation','extinction','texture'],['hom_biotite','hom_quartz','hom_orthoclase','nelson_inosilicates'])
